function gainSpecMappingLines = localBuildG1GainSpecDecodedOrderLines( ...
    g1Results)

manifestInputs = g1Results.Metrics.manifest_inputs;
channelContract = g1Results.Metrics.channel_contract;
gainSpecText = strtrim(string(manifestInputs.gain_spec));
channelLabels = [ ...
    localJoinStringVector(channelContract.channel_1_label); ...
    localJoinStringVector(channelContract.channel_2_label) ...
    ];
roleLabels = [ ...
    localInferChannelRoleLabel(channelLabels(1)); ...
    localInferChannelRoleLabel(channelLabels(2)) ...
    ];

if strlength(gainSpecText) == 0
    gainSpecMappingLines = "manifest gain_spec is empty.";
    return
end

gainTokens = split(gainSpecText, ",");
gainTokens = strtrim(gainTokens);
gainTokens = gainTokens(strlength(gainTokens) > 0);

mappingCount = min(numel(gainTokens), numel(channelLabels));
gainSpecMappingLines = strings(mappingCount, 1);

for idx = 1:mappingCount
    gainSpecMappingLines(idx) = sprintf("%s (%s) = %s dB", ...
        char(channelLabels(idx)), ...
        char(roleLabels(idx)), ...
        char(gainTokens(idx)));
end

if mappingCount == 0
    gainSpecMappingLines = "manifest gain_spec could not be parsed into " + ...
        "channel-aligned values.";
    return
end

gainSpecMappingLines = [ ...
    "manifest gain_spec follows the decoded channel order:"; ...
    gainSpecMappingLines ...
    ];

if numel(gainTokens) ~= numel(channelLabels)
    gainSpecMappingLines(end + 1) = ...
        "Parsed value count does not match decoded channel count exactly.";
end

end

