function interpretationText = localBuildG2Stage2PowerInterpretation(metrics)

medianPowerDelta = double( ...
    metrics.reference_minus_surveillance_power_db_median);

if medianPowerDelta < 0.0
    interpretationText = sprintf("Median reference minus surveillance power is %.3f dB. The accepted reference channel is weaker in whole-band in-band power, which points first to dataset, hardware, or acquisition limitations.", ...
        medianPowerDelta);
elseif medianPowerDelta < 3.0
    interpretationText = sprintf("Median reference minus surveillance power is %.3f dB. The accepted reference channel is stronger, but the margin is still modest.", ...
        medianPowerDelta);
else
    interpretationText = sprintf("Median reference minus surveillance power is %.3f dB. The accepted reference channel has a healthy whole-band power advantage.", ...
        medianPowerDelta);
end

end

function interpretationText = localBuildG2Stage2ClippingInterpretation( ...
    channelSummaryTable)

worstPeakHeadroom = min(channelSummaryTable.MinPeakHeadroom_dB);
worstNearRailFraction = max(channelSummaryTable.MaxNearRailFraction);

if worstNearRailFraction > 0.0
    interpretationText = sprintf("Worst near-rail fraction is %.6f and worst peak headroom is %.3f dB. Saturation pressure is present even though exact-rail clipping is not the main Stage 2 driver here.", ...
        worstNearRailFraction, worstPeakHeadroom);
else
    interpretationText = sprintf("Worst near-rail fraction is %.6f and worst peak headroom is %.3f dB. No severe clipping is reflected in the current Stage 2 verdict.", ...
        worstNearRailFraction, worstPeakHeadroom);
end

end

function interpretationText = localBuildG2Stage2DcInterpretation( ...
    channelSummaryTable)

worstDcSpike = max(channelSummaryTable.MaxDcSpike_dB);

if worstDcSpike >= 3.0
    interpretationText = sprintf("Worst DC spike is %.3f dB above the local PSD floor. DC or LO contamination is part of the current caveat set.", ...
        worstDcSpike);
else
    interpretationText = sprintf("Worst DC spike is %.3f dB above the local PSD floor. DC behavior is not the dominant Stage 2 concern in this session.", ...
        worstDcSpike);
end

end

function interpretationText = localBuildG2Stage2IqInterpretation( ...
    channelSummaryTable)

worstIqImpropriety = max(channelSummaryTable.MaxIqImpropriety);

if worstIqImpropriety >= 0.05
    interpretationText = sprintf("Worst IQ impropriety is %.4f. IQ and image behavior contributes to the current receiver caveat set.", ...
        worstIqImpropriety);
else
    interpretationText = sprintf("Worst IQ impropriety is %.4f. IQ and image proxies remain below the current diagnostic threshold.", ...
        worstIqImpropriety);
end

end

function interpretationText = localBuildG2Stage2ReceiverHealthInterpretation( ...
    channelSummaryTable)

worstNearRailFraction = max(channelSummaryTable.MaxNearRailFraction);
worstDcSpike = max(channelSummaryTable.MaxDcSpike_dB);
worstIqImpropriety = max(channelSummaryTable.MaxIqImpropriety);

if worstNearRailFraction > 0.0 || worstDcSpike >= 3.0 || ...
        worstIqImpropriety >= 0.05
    interpretationText = "At least one receiver-health proxy is part " + ...
        "of the current caveat set.";
else
    interpretationText = "Clipping, DC, and IQ proxies remain cleaner " + ...
        "than the role-based power-ordering result.";
end

end

function summaryTable = localBuildBlockedSummaryTable(stageName, reason)

summaryTable = table(string(stageName), "blocked", string(reason), ...
    'VariableNames', {'Stage', 'Status', 'Reason'});

end

function stringTable = localBuildStringListTable(columnName, values)

stringTable = table(string(values(:)), ...
    'VariableNames', {char(string(columnName))});

end

function joinedText = localJoinStringVector(values)

values = string(values(:));
values = strtrim(values);
values = values(strlength(values) > 0);

if isempty(values)
    joinedText = "";
    return
end

joinedText = strjoin(values, ", ");

end

function roleLabel = localInferChannelRoleLabel(channelLabel)

channelLabel = upper(strtrim(string(channelLabel)));

if contains(channelLabel, "RF0")
    roleLabel = "Surveillance";
elseif contains(channelLabel, "RF1")
    roleLabel = "Reference";
else
    roleLabel = "Unspecified";
end

end

function gateStatusTable = localBuildGateStatusTable(pipelineResults)

gateResults = pipelineResults.GateResults;
gateCount = numel(gateResults);
gateId = strings(gateCount, 1);
implemented = false(gateCount, 1);
executionStatus = strings(gateCount, 1);
decision = strings(gateCount, 1);
developmentStatus = strings(gateCount, 1);
bundleRoot = strings(gateCount, 1);
message = strings(gateCount, 1);

for idx = 1:gateCount
    gateId(idx) = gateResults(idx).GateId;
    implemented(idx) = gateResults(idx).Implemented;
    executionStatus(idx) = gateResults(idx).ExecutionStatus;
    decision(idx) = gateResults(idx).Decision;
    developmentStatus(idx) = gateResults(idx).DevelopmentStatus;
    bundleRoot(idx) = gateResults(idx).BundleRoot;
    message(idx) = gateResults(idx).Message;
end

gateStatusTable = table(gateId, implemented, executionStatus, decision, ...
    developmentStatus, bundleRoot, message, VariableNames = ...
    {'GateId', 'Implemented', 'ExecutionStatus', 'Decision', ...
    'DevelopmentStatus', 'BundleRoot', 'Message'});

end

function pipelineSummary = localBuildPipelineSummaryTable(pipelineResults)

pipelineSummary = table(pipelineResults.DatasetId, ...
    pipelineResults.RunTimestampZ, pipelineResults.PipelineStatus, ...
    pipelineResults.LastExecutedGate, pipelineResults.LastPassingGate, ...
    pipelineResults.NextGate, pipelineResults.DevelopmentStatus, ...
    numel(pipelineResults.ExecutedGates), ...
    VariableNames = {'DatasetId', 'RunTimestampZ', 'PipelineStatus', ...
    'LastExecutedGate', 'LastPassingGate', 'NextGate', ...
    'DevelopmentStatus', 'ExecutedGateCount'});

end

function value = localGateAllowsDownstreamDevelopment(gateResult)

executionAllowed = any(gateResult.ExecutionStatus == [ ...
    "executed"; ...
    "manual_review_executed" ...
    ]);
formalPass = gateResult.Decision == "pass";
developmentPass = any(gateResult.DevelopmentStatus == [ ...
    "ready_for_gate_progression"; ...
    "unblocked_with_dataset_caveat" ...
    ]);
value = executionAllowed && (formalPass || developmentPass);

end

function message = localBuildUpstreamBlockMessage(previousGate)

if previousGate.GateId == "G2_RF_Health" && ...
        previousGate.DevelopmentStatus == "blocked"
    message = "Later gate execution is blocked until G2 Stage 2 " + ...
        "establishes a trustworthy role mapping and receiver-integrity " + ...
        "interpretation.";
    return
end

if previousGate.GateId == "G2_RF_Health"
    message = "Later gate execution is blocked until the G2 manual-" + ...
        "review slices establish downstream development readiness.";
    return
end

message = "Later gate execution is blocked until the upstream gate has " + ...
    "executed and passed.";

end

function gateIdx = localFindGateIndex(pipelineResults, gateId)

gateIdx = find([pipelineResults.GateResults.GateId] == gateId, 1, "first");

if isempty(gateIdx)
    error("runPassiveBistaticPipeline:UnknownGate", ...
        "Unknown gate ID: %s", gateId);
end

end

function executedGates = localAppendExecutedGate(executedGates, gateId)

if any(executedGates == gateId)
    return
end

executedGates = [executedGates; gateId];

end


